#!/usr/bin/env python3
"""Generate src/tts/read_aloud_voice_table.inc from the vendored read_aloud crate.

The read_aloud C ABI takes numeric `Voice` enum values, while chatvv (and the
Flutter app) speak the Microsoft Edge voice names, e.g. "zh-CN-XiaoxiaoNeural".
This tool extracts the authoritative voice list from the vendored Rust sources:

  * the enumeration order from src/voices.rs (`pub enum Voice { ... }`),
  * the short Edge voice name from `impl From<Voice> for &str`
    ("Microsoft Server Speech Text to Speech Voice (zh-CN, XiaoxiaoNeural)").

The `VOICE_*` C identifiers are read from the cbindgen-generated read_aloud.h,
so the table cannot drift from what the compiler actually sees. The emitted file
is included inside an initializer list by src/tts/synthesize.cpp.

Usage:
  ./chatvv-gen-voice-table.py \
      --voices  src/voices.rs \
      --header  /path/to/cargo/target/release/read_aloud.h \
      --out     ../../../src/tts/read_aloud_voice_table.inc

The generated file is checked in; re-run this script only when updating the
vendored read_aloud version.
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

FROM_IMPL_RE = re.compile(
    r'Voice::(\w+)\s*=>\s*\{"Microsoft Server Speech Text to Speech Voice '
    r"\(([^,]+),\s*([^)]+)\)\"\}"
)
HEADER_ENUM_RE = re.compile(
    r"typedef\s+enum\s+Voice\s*\{(.*?)\}\s*Voice\s*;", re.DOTALL
)
HEADER_CONST_RE = re.compile(r"^\s*(VOICE_[A-Z0-9_]+)\s*,?\s*$", re.MULTILINE)


def camel_to_screaming_snake(name: str) -> str:
    """Approximate cbindgen/heck QualifiedScreamingSnakeCase for validation."""
    out = []
    prev = ""
    n = len(name)
    for i, ch in enumerate(name):
        if ch == "_":
            out.append("_")
            prev = ch
            continue
        if ch.isupper() and prev and prev != "_":
            prev_lower = prev.islower() or prev.isdigit()
            next_lower = i + 1 < n and name[i + 1].islower()
            if prev_lower or (prev.isupper() and next_lower):
                out.append("_")
        out.append(ch.upper())
        prev = ch
    return "".join(out)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--voices", required=True, help="path to src/voices.rs")
    parser.add_argument(
        "--header", required=True, help="path to cbindgen-generated read_aloud.h"
    )
    parser.add_argument("--out", required=True, help="output .inc path")
    args = parser.parse_args()

    voices_src = Path(args.voices).read_text(encoding="utf-8")
    header_src = Path(args.header).read_text(encoding="utf-8")

    entries = FROM_IMPL_RE.findall(voices_src)
    # The From impl lives after the enum; restrict to it to stay unambiguous.
    from_index = voices_src.find("impl From<Voice> for &str")
    if from_index < 0:
        sys.exit("error: could not find `impl From<Voice> for &str` in voices.rs")
    from_block = voices_src[from_index:]
    entries = FROM_IMPL_RE.findall(from_block)
    if not entries:
        sys.exit("error: no voice entries parsed from voices.rs")

    enum_block = voices_src.split("pub enum Voice {", 1)[1].split("\n}", 1)[0]
    enum_variants = re.findall(r"^\s{2}(\w+),?\s*$", enum_block, re.MULTILINE)

    header_enum = HEADER_ENUM_RE.search(header_src)
    if not header_enum:
        sys.exit("error: could not find `typedef enum Voice` in read_aloud.h")
    header_constants = HEADER_CONST_RE.findall(header_enum.group(1))

    if not (len(entries) == len(enum_variants) == len(header_constants)):
        sys.exit(
            "error: voice count mismatch: From impl=%d enum=%d header=%d"
            % (len(entries), len(enum_variants), len(header_constants))
        )

    rows = []
    seen = set()
    for index, ((variant, locale, name), enum_variant, constant) in enumerate(
        zip(entries, enum_variants, header_constants)
    ):
        if variant != enum_variant:
            sys.exit(
                "error: voice order mismatch at %d: From=%s enum=%s"
                % (index, variant, enum_variant)
            )
        derived = "VOICE_" + camel_to_screaming_snake(variant)
        if derived != constant:
            sys.exit(
                "error: %s does not match header constant %s (derived %s)"
                % (variant, constant, derived)
            )
        canonical = f"{locale}-{name}"
        key = canonical.lower()
        if key in seen:
            sys.exit(f"error: duplicate canonical voice name {canonical}")
        seen.add(key)
        rows.append((key, canonical, constant))

    rows.sort(key=lambda row: row[0])

    lines = [
        "// Generated by third_party/read_aloud/chatvv-gen-voice-table.py; DO NOT EDIT.",
        "// Canonical Microsoft Edge voice short name -> read_aloud Voice enum constant.",
        "// Sorted by case-insensitive name; synthesize.cpp binary-searches this table.",
    ]
    for _, canonical, constant in rows:
        lines.append(f'    {{"{canonical}", {constant}}},')
    lines.append("")
    Path(args.out).write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {len(rows)} voices to {args.out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
